import { readdir, readFile } from "node:fs/promises";
import path from "node:path";
import { createContext, Script } from "node:vm";

import {
  PUBLIC_ROOT,
  REPOSITORY_ROOT,
} from "./paths.js";

const EXERCISE_DATA_FILE = path.join(
  PUBLIC_ROOT,
  "content/exercise-data.js",
);
const EXERCISE_TESTS_ROOT = path.join(
  PUBLIC_ROOT,
  "content/exercise-tests",
);

async function loadClassicBrowserData(files) {
  const context = createContext({ window: {} });
  for (const file of files) {
    const source = await readFile(file, "utf8");
    new Script(source, { filename: file }).runInContext(context);
  }
  return context.window;
}

export async function loadCourseData() {
  const browserData = await loadClassicBrowserData([EXERCISE_DATA_FILE]);
  return browserData.COURSE_DATA;
}

export async function loadExerciseTests() {
  const entries = await readdir(EXERCISE_TESTS_ROOT, {
    withFileTypes: true,
  });
  const testFiles = entries
    .filter((entry) => (
      entry.isFile() &&
      /^tests-py\d+(?:-\d+)?\.js$/u.test(entry.name)
    ))
    .map((entry) => path.join(EXERCISE_TESTS_ROOT, entry.name))
    .sort();
  const browserData = await loadClassicBrowserData(testFiles);
  return browserData.EXERCISE_TESTS || {};
}

export async function collectSolutionCode(course) {
  const solutionCode = {};
  for (const chapter of course.chapters) {
    for (const exercise of chapter.exercises) {
      solutionCode[exercise.id] = await readFile(
        path.join(REPOSITORY_ROOT, exercise.file),
        "utf8",
      );
    }
  }
  return solutionCode;
}

export function renderSolutionBundle(solutionCode) {
  const banner =
    "// Generated by scripts/build/build-solution-bundle.js. Do not edit by hand.\n";
  return (
    `${banner}window.SOLUTION_CODE = ` +
    `${JSON.stringify(solutionCode, null, 2)};\n`
  );
}

export function createStarterCode(course, solutions, specs) {
  const starters = {};
  for (const chapter of course.chapters) {
    for (const exercise of chapter.exercises) {
      const id = String(exercise.id);
      const spec = specs[id];

      if (!spec) {
        throw new Error(`${id}: missing test specification.`);
      }

      if (spec.mode === "script") {
        starters[id] = [
          "# Write your program below.",
          "# Read the contract and visible examples before you begin.",
          "",
        ].join("\n");
        continue;
      }

      const source = solutions[id] || "";
      const calls = spec.tests.map((test) => test.call || "").join("\n");
      const signatures = [
        ...source.matchAll(
          /^def\s+([A-Za-z_]\w*)\s*\(([\s\S]*?)\)\s*(?:->\s*[^:\n]+)?\s*:/gm,
        ),
      ]
        .filter((match) => (
          new RegExp(`\\b${match[1]}\\s*\\(`).test(calls)
        ))
        .map((match) => match[0]);

      if (signatures.length === 0) {
        throw new Error(
          `${id}: could not find a tested public function signature.`,
        );
      }

      starters[id] = [
        "# Keep these public function names and parameters so the tests can call your code.",
        ...signatures.flatMap((signature, index) => [
          ...(index === 0 ? [] : [""]),
          signature,
          "    # TODO: replace pass with your implementation.",
          "    pass",
        ]),
        "",
      ].join("\n");
    }
  }
  return starters;
}

export function renderStarterBundle(starters) {
  return [
    "// Generated by scripts/build/build-starter-bundle.js. Do not edit by hand.",
    "// This bundle contains public signatures only; repository solutions stay private.",
    `window.STARTER_CODE = ${JSON.stringify(starters, null, 2)};`,
    "",
  ].join("\n");
}
